package Module1;

public class CalculateAreawithoutStaticMethod {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int  a=10;
double squareArea=a*a;
double PerimeterOfSquare=4*a;
System.out.println("Area of Square "+squareArea);
System.out.println("Perimeter of Square "+PerimeterOfSquare);
 int l=5;
 int b=12;
 double AreaOfRectangle=l*b;
 double PerimeterOfRectangle=2*(l+b);
 System.out.println("Area of Rectangle "+AreaOfRectangle);
 System.out.println("Perimeter of Rectangle "+PerimeterOfRectangle);
 double b1=11;
 double h=10;
 double p=5;
 double AreaOfTriangle=0.5*b1*h;
 double PerimeterOfTriangle=b+h+p;
 System.out.println("Area of Triangle "+AreaOfTriangle);
 System.out.println("Perimeter of Triangle "+PerimeterOfTriangle);
 int r=8;
 double Pi=3.14;
 double AreaOfCircle=Pi*r*r;
 double CircumferenceOfCircle=2*Pi*r;
 System.out.println("Area of Circle "+AreaOfCircle);
 System.out.println("Perimeter of Circle "+CircumferenceOfCircle);
 
	}

}
